package com.agacostays.payroll.service.impl; import com.agacostays.payroll.dto.response.*;import com.agacostays.payroll.entity.Payroll;import com.agacostays.payroll.enums.PayrollStatus;import com.agacostays.payroll.repository.PayrollRepository;import com.agacostays.payroll.service.PayrollReportService;import org.springframework.stereotype.Service;import java.math.BigDecimal;import java.util.*;@Service public class PayrollReportServiceImpl implements PayrollReportService{final PayrollRepository repo;public PayrollReportServiceImpl(PayrollRepository r){repo=r;}public PayrollSummaryResponse monthlySummary(int m,int y){List<Payroll>a=repo.findByMonthAndYear(m,y);BigDecimal g=sum(a,true),n=sum(a,false);long paid=a.stream().filter(x->x.getPaymentStatus()==PayrollStatus.PAID).count(),failed=a.stream().filter(x->x.getPaymentStatus()==PayrollStatus.FAILED).count();return new PayrollSummaryResponse(m,y,a.size(),g,n,paid,a.size()-paid-failed,failed);}public List<PayrollReportResponse> byRole(int m,int y){return agg(repo.findByMonthAndYear(m,y),p->String.valueOf(p.getRoleId()));}public List<PayrollReportResponse> byDepartment(int m,int y){return agg(repo.findByMonthAndYear(m,y),p->p.getDepartment()==null?"UNKNOWN":p.getDepartment());}public List<PayrollReportResponse> payments(int m,int y){return agg(repo.findByMonthAndYear(m,y),p->p.getPaymentStatus().name());}public List<PayrollReportResponse> branchWise(){return agg(repo.findAll(),p->String.valueOf(p.getBranchId()));}private BigDecimal sum(List<Payroll>a,boolean g){return a.stream().map(p->g?p.getGrossSalary():p.getNetSalary()).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);}private List<PayrollReportResponse> agg(List<Payroll>a,java.util.function.Function<Payroll,String> f){Map<String,List<Payroll>>m=new LinkedHashMap<>();a.forEach(p->m.computeIfAbsent(f.apply(p),k->new ArrayList<>()).add(p));return m.entrySet().stream().map(e->new PayrollReportResponse(e.getKey(),e.getKey(),e.getValue().size(),sum(e.getValue(),true),sum(e.getValue(),false))).toList();}}
